<style>
.sz-pay-overlay{position:fixed;inset:0;background:rgba(6,23,43,.55);z-index:9998;opacity:0;visibility:hidden;transition:opacity .25s,visibility .25s;backdrop-filter:blur(2px)}
.sz-pay-drawer{position:fixed;right:0;top:0;bottom:0;width:min(560px,100vw);background:#fff;z-index:9999;transform:translateX(102%);transition:transform .3s cubic-bezier(.2,.8,.2,1);box-shadow:-18px 0 55px #071e3840}
.sz-pay-overlay.is-open{opacity:1;visibility:visible}.sz-pay-drawer.is-open{transform:translateX(0)}.sz-pay-frame{border:0;width:100%;height:100%;display:block}
.sz-pay-loading{position:absolute;inset:0;display:grid;place-items:center;background:#f6f9fd;color:#10518f;font:700 16px Cairo,Tahoma,sans-serif}.sz-pay-drawer.loaded .sz-pay-loading{display:none}
@media(prefers-reduced-motion:reduce){.sz-pay-drawer,.sz-pay-overlay{transition:none}}
</style>
<div class="sz-pay-overlay" id="sz-pay-overlay" aria-hidden="true"></div>
<div class="sz-pay-drawer" id="sz-pay-drawer" role="dialog" aria-modal="true" aria-label="إتمام التبرع" aria-hidden="true"><div class="sz-pay-loading">جاري تجهيز نموذج التبرع…</div><iframe id="sz-pay-frame" class="sz-pay-frame" title="الدفع بالحوالة المصرفية" loading="lazy"></iframe></div>
<script>
(function(){const overlay=document.getElementById('sz-pay-overlay'),drawer=document.getElementById('sz-pay-drawer'),frame=document.getElementById('sz-pay-frame');let oldOverflow='',previousFocus=null;
function close(){drawer.classList.remove('is-open','loaded');overlay.classList.remove('is-open');drawer.setAttribute('aria-hidden','true');overlay.setAttribute('aria-hidden','true');document.body.style.overflow=oldOverflow;frame.removeAttribute('src');if(previousFocus)previousFocus.focus()}
function open(url){previousFocus=document.activeElement;oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';drawer.classList.add('is-open');overlay.classList.add('is-open');drawer.setAttribute('aria-hidden','false');overlay.setAttribute('aria-hidden','false');const u=new URL(url,location.href);u.searchParams.set('embedded','1');frame.src=u.toString()}
document.querySelectorAll('a.sz-open-payment').forEach(a=>a.addEventListener('click',function(e){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();open(this.href)}));overlay.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer.classList.contains('is-open'))close()});frame.addEventListener('load',()=>drawer.classList.add('loaded'));window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data&&e.data.type==='sirte-close-payment')close()});
})();
</script>
<script>(function(){document.querySelectorAll('.sz-edge-controls').forEach(group=>{const buttons=[...group.querySelectorAll('[data-slide]')];const track=document.getElementById(buttons[0]?.dataset.slide);if(!track)return;const cards=[...track.querySelectorAll('.sz-showcase-card')];const update=()=>{const max=Math.max(0,track.scrollWidth-track.clientWidth);const rtl=getComputedStyle(track).direction==='rtl';const current=rtl?-track.scrollLeft:track.scrollLeft;buttons.forEach(b=>{b.disabled=Number(b.dataset.direction)<0?current<=3:current>=max-3});if(cards.length<=1)buttons.forEach(b=>b.disabled=true)};buttons.forEach(b=>b.addEventListener('click',()=>{const rtl=getComputedStyle(track).direction==='rtl';const step=(cards[0]?.getBoundingClientRect().width||320)+18;const direction=Number(b.dataset.direction);track.scrollBy({left:(rtl?-1:1)*direction*step,behavior:'smooth'});setTimeout(update,420)}));track.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update);update()})})();</script></body></html>